<section class="page-head"><span class="eyebrow">DOCTOR REGISTRATION</span><h1>Join the Health Setu clinical network</h1><p>Registration remains pending until Super Admin verification.</p></section><form class="form-card wide" method="post" enctype="multipart/form-data"><label>Profile Photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><span class="hint">Upload a clear profile photo (JPG, PNG or WEBP).</span></label><div class="grid2"><label>Full Name<input name="name" required></label><label>Phone Number<input name="phone" maxlength="15" required></label><label>Email<input type="email" name="email" required></label><label>Aadhaar Number<input name="aadhaar_no" maxlength="12" pattern="[0-9]{12}" required></label><label>PAN Number<input name="pan_no" maxlength="10" style="text-transform:uppercase" required></label><label>Date of Birth<input type="date" name="dob"></label><label>Gender<select name="gender"><option value="">Select</option><option>Male</option><option>Female</option><option>Other</option></select></label><label>Blood Group<select name="blood_group"><option value="">Select</option><option>A+</option><option>A-</option><option>B+</option><option>B-</option><option>AB+</option><option>AB-</option><option>O+</option><option>O-</option></select></label></div><?php include __DIR__.'/../address_fields.php';?><h3>Professional Details</h3><div class="grid2"><label>Specialization<select name="specialization_id" required><option value="">Select specialization</option><?php foreach($specializations as $s):?><option value="<?=$s['id']?>"><?=$s['name']?></option><?php endforeach?></select></label><label>Medical Registration Number<input name="medical_registration_no" required></label><label>Registration Council<input name="registration_council" required></label><label>Experience (Years)<input type="number" name="experience_years" min="0"></label><label>Degree / Qualification<input name="degree" placeholder="MBBS, MD..."></label><label>Degree Number<input name="degree_number"></label><label>Institute<input name="institute"></label><label>University<input name="university"></label><label>Passing Year<input type="number" name="passing_year" min="1950" max="2100"></label><label>Hospital / Clinic<select name="hospital_id"><option value="">Independent / select later</option><?php foreach($hospitals as $h):?><option value="<?=$h['id']?>"><?=$h['name']?></option><?php endforeach?></select></label><label>OPD Fee ₹<input type="number" name="consultation_fee" min="0"></label><label>Video Fee ₹<input type="number" name="video_fee" min="0"></label><label>Emergency Fee ₹<input type="number" name="emergency_fee" min="0"></label></div><label>Professional Bio<textarea name="bio"></textarea></label><div class="grid2"><label>Password<input type="password" name="password" data-password required></label><label>Confirm Password<input type="password" name="confirm_password" required></label></div><div class="password-box"><b>Password instructions</b><span>8+ characters, uppercase, lowercase, number and special character</span><strong data-strength>Strength: —</strong></div><button class="btn primary">Submit for Verification</button></form>